// Operator sign-in: one password (scrypt hash in env), optional TOTP, and a
// signed, expiring, httpOnly cookie. Pure helpers here; cookie reading/writing
// is in lib/auth.ts so this file stays testable.
import { createHmac, randomBytes, scryptSync, timingSafeEqual } from "node:crypto";

export const SESSION_COOKIE = "platform_session";
export const SESSION_TTL_SECONDS = 8 * 60 * 60;
const MIN_SESSION_SECRET = 32;

const SCRYPT = { N: 16384, r: 8, p: 1, keylen: 32 };

/** "scrypt$<salt b64>$<hash b64>" -- generated by scripts/hash-password.mjs. */
export function hashPassword(password: string, salt: Buffer = randomBytes(16)): string {
  const hash = scryptSync(password, salt, SCRYPT.keylen, { N: SCRYPT.N, r: SCRYPT.r, p: SCRYPT.p });
  return `scrypt$${salt.toString("base64")}$${hash.toString("base64")}`;
}

export function verifyPassword(password: string, stored: string | undefined): boolean {
  if (!stored) return false;
  const parts = stored.split("$");
  if (parts.length !== 3 || parts[0] !== "scrypt") return false;
  const salt = Buffer.from(parts[1]!, "base64");
  const want = Buffer.from(parts[2]!, "base64");
  if (salt.length === 0 || want.length !== SCRYPT.keylen) return false;
  const got = scryptSync(password, salt, SCRYPT.keylen, { N: SCRYPT.N, r: SCRYPT.r, p: SCRYPT.p });
  return timingSafeEqual(got, want);
}

function sign(secret: string, payload: string): string {
  return createHmac("sha256", secret).update(payload).digest("base64url");
}

export function createSessionToken(secret: string, nowSeconds = Math.floor(Date.now() / 1000)): string {
  if (secret.length < MIN_SESSION_SECRET) throw new Error("SESSION_SECRET must be at least 32 characters.");
  const payload = Buffer.from(JSON.stringify({ exp: nowSeconds + SESSION_TTL_SECONDS })).toString("base64url");
  return `${payload}.${sign(secret, payload)}`;
}

export function verifySessionToken(
  secret: string | undefined,
  token: string | undefined,
  nowSeconds = Math.floor(Date.now() / 1000)
): boolean {
  if (!secret || secret.length < MIN_SESSION_SECRET || !token) return false;
  const [payload, sig] = token.split(".");
  if (!payload || !sig) return false;
  const a = Buffer.from(sign(secret, payload));
  const b = Buffer.from(sig);
  if (a.length !== b.length || !timingSafeEqual(a, b)) return false;
  try {
    const { exp } = JSON.parse(Buffer.from(payload, "base64url").toString("utf8")) as { exp?: unknown };
    return typeof exp === "number" && exp > nowSeconds;
  } catch {
    return false;
  }
}
